name: backoffice CI

on:
  push:
    branches:
      - master
      - staging
      - qa

jobs:
  pipeline:
    uses: liftitapp/workflows-templates/.github/workflows/smart-pipeline.yml@main
    with:
      deploy_type: helm
      app: backoffice-api
      cluster_name: ${{ github.ref_name == 'qa' && 'lms-gke-qa' || github.ref_name == 'staging' && 'lms-gke-staging' || 'lms-gke-prod' }}
      copy_templates: true
      enable_sonarqube: false
      enable_flyway: true
      notify_on_failure: true
    secrets:
      GCP_SA_KEY: ${{ github.ref_name == 'qa' && secrets.GCP_SA_KEY_IAC_QA || github.ref_name == 'staging' && secrets.GCP_SA_KEY_IAC_STAGING || secrets.GCP_SA_KEY_IAC_PROD }}
      GCP_SA_KEY_BUILD: ${{ secrets.GCP_SA_KEY_IAC_SHA }}
      GCP_PROJECT_ID: ${{ secrets.GCP_PROJECT_ID_SHA }}
      GCP_SOPS_KMS: ${{ github.ref_name == 'qa' && secrets.GCP_SOPS_LOWENV_NEW || github.ref_name == 'staging' && secrets.GCP_SOPS_LOWENV_NEW || secrets.GCP_SOPS_PROD }}
      GH_ACCESS_TOKEN: ${{ secrets.GH_ACCESS_TOKEN }}
      DB_URL: ${{ github.ref_name == 'qa' && secrets.FLYWAY_HOST_QA || github.ref_name == 'staging' && secrets.FLYWAY_HOST_STAGING || secrets.FLYWAY_HOST }}
      DB_USER: ${{ github.ref_name == 'qa' && secrets.FLYWAY_QA_USER || github.ref_name == 'staging' && secrets.FLYWAY_STG_USER || secrets.FLYWAY_PROD_USER }}
      DB_PASSWORD: ${{ github.ref_name == 'qa' && secrets.FLYWAY_QA_PASS || github.ref_name == 'staging' && secrets.FLYWAY_STG_PASS || secrets.FLYWAY_PROD_PASS }}
      WG_CONFIG: ${{ secrets.WIREGUARD_CONF }}
      SLACK_WEBHOOK: ${{ secrets.SLACK_WEBHOOK }}

